from rdkit import Chem
import itertools

smi = "C123CCC(C(C)(/C=C/C=C(\\C)/C(=O)O)OC(=O)3)C1(OC(=O)C)CCC(C(=O)OC)=CC2"
target = {0:'R', 3:'S', 4:'R', 17:'S'}

results = []
for combo in itertools.product([Chem.ChiralType.CHI_TETRAHEDRAL_CW, Chem.ChiralType.CHI_TETRAHEDRAL_CCW], repeat=4):
    m = Chem.MolFromSmiles(smi)
    for idx, ct in zip([0,3,4,17], combo):
        m.GetAtomWithIdx(idx).SetChiralTag(ct)
    Chem.AssignStereochemistry(m, cleanIt=True, force=True)
    labels = {}
    for idx in [0,3,4,17]:
        a = m.GetAtomWithIdx(idx)
        labels[idx] = a.GetProp('_CIPCode') if a.HasProp('_CIPCode') else '?'
    if labels == target:
        results.append(combo)
        print("MATCH:", combo, labels, Chem.MolToSmiles(m, isomericSmiles=True))
print("total matches:", len(results))
EOF
